 25→}
 26→
 27→type CreateTaskOutput struct {
 28→	Success bool   `json:"success"`
 29→	Message string `json:"message"`
 30→}
 31→
 32→type GetTasksInput struct {
 33→	ProjectID string `json:"project_id,omitempty" jsonschema:"Filter tasks by project ID (optional)"`
 34→	Filter    string `json:"filter,omitempty" jsonschema:"Natural language filter like 'today', 'tomorrow', 'next week', 'priority 1', 'overdue' (optional)"`
 35→	Priority  int    `json:"priority,omitempty" jsonschema:"Filter by priority level (1-4) (optional)"`
