 90→// --- helpers ---
 91→
 92→func resolveTaskID(c *todoist.Client, id, name string) (string, string, error) {
 93→	if id != "" {
 94→		return id, "", nil
 95→	}
 96→	if name == "" {
 97→		return "", "", fmt.Errorf("either task_id or task_name is required")
 98→	}
 99→	task, err := c.FindTaskByName(name)
100→	if err != nil {
101→		return "", "", err
102→	}
103→	if task == nil {
104→		return "", "", nil // not found
105→	}
106→	return task.ID, task.Content, nil
107→}
108→
109→func textResult(msg string, isError bool) *mcp.CallToolResult {
110→	return &mcp.CallToolResult{
111→		Content: []mcp.Content{&mcp.TextContent{Text: msg}},
112→		IsError: isError,
113→	}
114→}
