118→func registerTaskTools(s *mcp.Server, c *todoist.Client) {
119→	mcp.AddTool(s, &mcp.Tool{
120→		Name:        "todoist_create_task",
121→		Description: "Create a new task in Todoist with optional description, due date, priority, project, section, labels, and assignee",
122→	}, func(ctx context.Context, req *mcp.CallToolRequest, input CreateTaskInput) (*mcp.CallToolResult, CreateTaskOutput, error) {
123→		body := map[string]any{"content": input.Content}
124→		if input.Description != "" {
125→			body["description"] = input.Description
126→		}
127→		if input.DueString != "" {
128→			body["due_string"] = input.DueString
129→		}
130→		if input.Priority > 0 && input.Priority <= 4 {
131→			body["priority"] = input.Priority
132→		}
133→		if input.ProjectID != "" {
134→			body["project_id"] = input.ProjectID
135→		}
136→		if input.SectionID != "" {
137→			body["section_id"] = input.SectionID
138→		}
139→		if input.ParentID != "" {
140→			body["parent_id"] = input.ParentID
141→		}
142→		if len(input.Labels) > 0 {
143→			body["labels"] = input.Labels
144→		}
145→		if input.AssigneeID != "" {
146→			body["assignee_id"] = input.AssigneeID
147→		}
148→
149→		task, err := c.CreateTask(body)
150→		if err != nil {
151→			return nil, CreateTaskOutput{Success: false, Message: err.Error()}, err
152→		}
153→
154→		msg := fmt.Sprintf("Task created:\nTitle: %s", task.Content)
155→		if task.Description != "" {
156→			msg += fmt.Sprintf("\nDescription: %s", task.Description)
157→		}
158→		if task.Due != nil && task.Due.String != "" {
159→			msg += fmt.Sprintf("\nDue: %s", task.Due.String)
160→		}
161→		if task.Priority > 0 {
162→			msg += fmt.Sprintf("\nPriority: %d", task.Priority)
163→		}
164→
165→		return textResult(msg, false), CreateTaskOutput{Success: true, Message: msg}, nil
166→	})
167→
168→	mcp.AddTool(s, &mcp.Tool{
169→		Name:        "todoist_get_tasks",
170→		Description: "Get a list of tasks from Todoist with various filters",
171→	}, func(ctx context.Context, req *mcp.CallToolRequest, input GetTasksInput) (*mcp.CallToolResult, GetTasksOutput, error) {
172→		var tasks []models.Task
173→		var err error
174→		if input.Filter != "" {
175→			tasks, err = c.GetTasksByFilter(input.Filter)
176→		} else {
177→			tasks, err = c.GetTasks(input.ProjectID)
178→		}
179→		if err != nil {
180→			return nil, GetTasksOutput{}, err
181→		}
182→
183→		// Apply priority filter.
184→		if input.Priority > 0 && input.Priority <= 4 {
185→			filtered := tasks[:0]
186→			for _, t := range tasks {
187→				if t.Priority == input.Priority {
188→					filtered = append(filtered, t)
189→				}
190→			}
191→			tasks = filtered
192→		}
193→
194→		// Apply limit.
195→		limit := input.Limit
196→		if limit == 0 {
197→			limit = 10
198→		}
199→		if len(tasks) > limit {
200→			tasks = tasks[:limit]
201→		}
202→
203→		var msg string
204→		if len(tasks) == 0 {
205→			msg = "No tasks found matching the criteria"
206→		} else {
207→			var lines []string
208→			for _, t := range tasks {
209→				s := fmt.Sprintf("- %s (ID: %s)", t.Content, t.ID)
210→				if t.Description != "" {
211→					s += fmt.Sprintf("\n  Description: %s", t.Description)
212→				}
213→				if t.Due != nil && t.Due.String != "" {
214→					s += fmt.Sprintf("\n  Due: %s", t.Due.String)
215→				}
216→				if t.Priority > 0 {
217→					s += fmt.Sprintf("\n  Priority: %d", t.Priority)
218→				}
219→				lines = append(lines, s)
220→			}
221→			msg = strings.Join(lines, "\n\n")
222→		}
223→
224→		return textResult(msg, false), GetTasksOutput{Success: true, Message: msg}, nil
225→	})
