227→	mcp.AddTool(s, &mcp.Tool{
228→		Name:        "todoist_update_task",
229→		Description: "Update an existing task in Todoist by task_id or by searching by name",
230→	}, func(ctx context.Context, req *mcp.CallToolRequest, input UpdateTaskInput) (*mcp.CallToolResult, UpdateTaskOutput, error) {
231→		id, originalName, err := resolveTaskID(c, input.TaskID, input.TaskName)
232→		if err != nil {
233→			return nil, UpdateTaskOutput{Success: false, Message: err.Error()}, err
234→		}
235→		if id == "" {
236→			msg := fmt.Sprintf("Could not find a task matching \"%s\"", input.TaskName)
237→			return textResult(msg, true), UpdateTaskOutput{Success: false, Message: msg}, nil
238→		}
239→
240→		body := map[string]any{}
241→		if input.Content != "" {
242→			body["content"] = input.Content
243→		}
244→		if input.Description != "" {
245→			body["description"] = input.Description
246→		}
247→		if input.DueString != "" {
248→			body["due_string"] = input.DueString
249→		}
250→		if input.Priority > 0 && input.Priority <= 4 {
251→			body["priority"] = input.Priority
252→		}
253→		if len(input.Labels) > 0 {
254→			body["labels"] = input.Labels
255→		}
256→		if input.AssigneeID != "" {
257→			body["assignee_id"] = input.AssigneeID
258→		}
259→
260→		updated, err := c.UpdateTask(id, body)
261→		if err != nil {
262→			return nil, UpdateTaskOutput{Success: false, Message: err.Error()}, err
263→		}
264→
265→		label := originalName
266→		if label == "" {
267→			label = id
268→		}
269→		msg := fmt.Sprintf("Task \"%s\" updated:\nNew Title: %s", label, updated.Content)
270→		if updated.Description != "" {
271→			msg += fmt.Sprintf("\nNew Description: %s", updated.Description)
272→		}
273→		if updated.Due != nil && updated.Due.String != "" {
274→			msg += fmt.Sprintf("\nNew Due Date: %s", updated.Due.String)
275→		}
276→		if updated.Priority > 0 {
277→			msg += fmt.Sprintf("\nNew Priority: %d", updated.Priority)
278→		}
279→
280→		return textResult(msg, false), UpdateTaskOutput{Success: true, Message: msg}, nil
281→	})
