 13→// FilteredTasksResponse wraps the /tasks/filter endpoint response which uses
 14→// "items" instead of "results".
 15→type FilteredTasksResponse struct {
 16→	Items      []models.Task `json:"items"`
 17→	NextCursor string        `json:"next_cursor"`
 18→}
 19→
 20→// getTasksPage returns one page of active tasks plus the cursor for the next page.
 21→func (c *Client) getTasksPage(projectID, cursor string) ([]models.Task, string, error) {
 22→	endpoint := "/tasks"
 23→	values := url.Values{}
 24→	if projectID != "" {
 25→		values.Set("project_id", projectID)
 26→	}
 27→	if cursor != "" {
 28→		values.Set("cursor", cursor)
 29→	}
 30→	if len(values) > 0 {
 31→		endpoint += "?" + values.Encode()
 32→	}
 33→
 34→	data, err := c.do("GET", endpoint, nil)
 35→	if err != nil {
 36→		return nil, "", err
 37→	}
 38→
 39→	var page PaginatedResponse[models.Task]
 40→	if err := json.Unmarshal(data, &page); err != nil {
 41→		return nil, "", fmt.Errorf("failed to parse tasks: %w", err)
 42→	}
 43→	return page.Results, page.NextCursor, nil
 44→}
 45→
 46→// GetTasks returns the first page of active tasks, optionally filtered by project.
 47→func (c *Client) GetTasks(projectID string) ([]models.Task, error) {
 48→	tasks, _, err := c.getTasksPage(projectID, "")
 49→	return tasks, err
 50→}
 51→
 52→// GetTasksByFilter returns tasks matching a Todoist filter query using the
 53→// dedicated /tasks/filter endpoint.
 54→func (c *Client) GetTasksByFilter(query string) ([]models.Task, error) {
 55→	endpoint := "/tasks/filter"
 56→	values := url.Values{}
 57→	values.Set("query", query)
 58→	endpoint += "?" + values.Encode()
 59→
 60→	data, err := c.do("GET", endpoint, nil)
 61→	if err != nil {
 62→		return nil, err
 63→	}
 64→
 65→	var resp FilteredTasksResponse
 66→	if err := json.Unmarshal(data, &resp); err != nil {
 67→		return nil, fmt.Errorf("failed to parse filtered tasks: %w", err)
 68→	}
 69→	return resp.Items, nil
 70→}
 71→
 72→// GetTask returns a single task by ID.
 73→func (c *Client) GetTask(id string) (*models.Task, error) {
 74→	data, err := c.do("GET", "/tasks/"+id, nil)
 75→	if err != nil {
 76→		return nil, err
 77→	}
 78→
 79→	var task models.Task
 80→	if err := json.Unmarshal(data, &task); err != nil {
 81→		return nil, fmt.Errorf("failed to parse task: %w", err)
 82→	}
 83→	return &task, nil
 84→}
 85→
 86→// CreateTask creates a new task.
 87→func (c *Client) CreateTask(body map[string]any) (*models.Task, error) {
 88→	data, err := c.do("POST", "/tasks", body)
 89→	if err != nil {
 90→		return nil, err
 91→	}
 92→
 93→	var task models.Task
 94→	if err := json.Unmarshal(data, &task); err != nil {
 95→		return nil, fmt.Errorf("failed to parse task: %w", err)
 96→	}
 97→	return &task, nil
 98→}
 99→
100→// UpdateTask updates an existing task.
101→func (c *Client) UpdateTask(id string, body map[string]any) (*models.Task, error) {
102→	data, err := c.do("POST", "/tasks/"+id, body)
103→	if err != nil {
104→		return nil, err
105→	}
106→
107→	var task models.Task
108→	if err := json.Unmarshal(data, &task); err != nil {
109→		return nil, fmt.Errorf("failed to parse task: %w", err)
110→	}
111→	return &task, nil
112→}
