 10→func TestGetTasks(t *testing.T) {
 11→	c, srv := testServer(t, func(w http.ResponseWriter, r *http.Request) {
 12→		if r.Method != http.MethodGet {
 13→			t.Errorf("method = %s", r.Method)
 14→		}
 15→		if r.URL.Path != "/tasks" {
 16→			t.Errorf("path = %s", r.URL.Path)
 17→		}
 18→		_, _ = w.Write([]byte(`{"results":[{"id":"1","content":"Test task","priority":1}],"next_cursor":""}`))
 19→	})
 20→	defer srv.Close()
 21→
 22→	tasks, err := c.GetTasks("")
 23→	if err != nil {
 24→		t.Fatal(err)
 25→	}
 26→	if len(tasks) != 1 {
 27→		t.Fatalf("got %d tasks", len(tasks))
 28→	}
 29→	if tasks[0].Content != "Test task" {
 30→		t.Errorf("content = %q", tasks[0].Content)
 31→	}
 32→}
