 1→package todoist
 2→
 3→import (
 4→	"encoding/json"
 5→	"fmt"
 6→	"io"
 7→	"net/http"
 8→	"strings"
 9→	"time"
10→)
11→
12→const defaultBaseURL = "https://api.todoist.com/api/v1"
13→
14→// Client is an HTTP client for the Todoist API v1.
15→type Client struct {
16→	token      string
17→	baseURL    string
18→	httpClient *http.Client
19→}
20→
21→// PaginatedResponse wraps list endpoints in the Todoist API v1.
22→type PaginatedResponse[T any] struct {
23→	Results    []T    `json:"results"`
24→	NextCursor string `json:"next_cursor"`
25→}
26→
27→// Option configures a Client.
28→type Option func(*Client)
29→
30→// WithHTTPClient sets a custom http.Client.
31→func WithHTTPClient(c *http.Client) Option {
32→	return func(cl *Client) { cl.httpClient = c }
33→}
34→
35→// WithBaseURL overrides the API base URL (useful for testing).
36→func WithBaseURL(url string) Option {
37→	return func(cl *Client) { cl.baseURL = url }
38→}
39→
40→// NewClient creates a new Todoist API client.
41→func NewClient(token string, opts ...Option) *Client {
42→	c := &Client{
43→		token:      token,
44→		baseURL:    defaultBaseURL,
45→		httpClient: &http.Client{Timeout: 10 * time.Second},
46→	}
47→	for _, o := range opts {
48→		o(c)
49→	}
50→	return c
51→}
52→
53→// do executes an HTTP request against the Todoist API and returns the
54→// response body bytes. For responses with no content (204) it returns nil.
55→func (c *Client) do(method, endpoint string, body any) ([]byte, error) {
56→	var reqBody io.Reader
57→	if body != nil {
58→		data, err := json.Marshal(body)
59→		if err != nil {
60→			return nil, fmt.Errorf("failed to marshal request body: %w", err)
61→		}
62→		reqBody = strings.NewReader(string(data))
63→	}
64→
65→	req, err := http.NewRequest(method, c.baseURL+endpoint, reqBody)
66→	if err != nil {
67→		return nil, fmt.Errorf("failed to create request: %w", err)
68→	}
69→
70→	req.Header.Set("Authorization", "Bearer "+c.token)
71→	req.Header.Set("Content-Type", "application/json")
72→
73→	resp, err := c.httpClient.Do(req)
74→	if err != nil {
75→		return nil, fmt.Errorf("failed to make request: %w", err)
76→	}
77→	defer func() { _ = resp.Body.Close() }()
78→
79→	respBody, err := io.ReadAll(resp.Body)
80→	if err != nil {
81→		return nil, fmt.Errorf("failed to read response: %w", err)
82→	}
83→
84→	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
85→		return nil, fmt.Errorf("API request failed with status %d: %s", resp.StatusCode, string(respBody))
86→	}
87→
88→	if resp.StatusCode == http.StatusNoContent {
89→		return nil, nil
90→	}
91→
92→	return respBody, nil
93→}
