  1→package tools
  2→
  3→import (
  4→	"context"
  5→	"net/http"
  6→	"net/http/httptest"
  7→	"strings"
  8→	"sync"
  9→	"testing"
 10→
 11→	"github.com/modelcontextprotocol/go-sdk/mcp"
 12→	"github.com/nsega/mcp-todoist/internal/todoist"
 13→)
 14→
 15→// router dispatches to handlers based on method+path prefix.
 16→type router struct {
 17→	mu       sync.Mutex
 18→	handlers []routeEntry
 19→}
 20→
 21→type routeEntry struct {
 22→	method  string
 23→	prefix  string
 24→	handler http.HandlerFunc
 25→}
 26→
 27→func newRouter() *router {
 28→	return &router{}
 29→}
 30→
 31→func (rt *router) handle(method, prefix string, h http.HandlerFunc) {
 32→	rt.mu.Lock()
 33→	defer rt.mu.Unlock()
 34→	rt.handlers = append(rt.handlers, routeEntry{method, prefix, h})
 35→}
 36→
 37→func (rt *router) ServeHTTP(w http.ResponseWriter, r *http.Request) {
 38→	rt.mu.Lock()
 39→	handlers := make([]routeEntry, len(rt.handlers))
 40→	copy(handlers, rt.handlers)
 41→	rt.mu.Unlock()
 42→
 43→	// Match longest prefix first for specificity.
 44→	var best *routeEntry
 45→	for i := range handlers {
 46→		e := &handlers[i]
 47→		if r.Method == e.method && strings.HasPrefix(r.URL.Path, e.prefix) {
 48→			if best == nil || len(e.prefix) > len(best.prefix) {
 49→				best = e
 50→			}
 51→		}
 52→	}
 53→	if best != nil {
 54→		best.handler(w, r)
 55→		return
 56→	}
 57→	w.WriteHeader(http.StatusNotFound)
 58→}
 59→
 60→func setupTest(t *testing.T, rt *router) (*mcp.ClientSession, func()) {
 61→	t.Helper()
 62→	apiSrv := httptest.NewServer(rt)
 63→	client := todoist.NewClient("test-token", todoist.WithBaseURL(apiSrv.URL))
 64→
 65→	mcpServer := mcp.NewServer(&mcp.Implementation{Name: "test", Version: "0.0.1"}, nil)
 66→	RegisterAll(mcpServer, client)
 67→
 68→	ct, st := mcp.NewInMemoryTransports()
 69→	ctx := context.Background()
 70→
 71→	sSession, err := mcpServer.Connect(ctx, st, nil)
 72→	if err != nil {
 73→		t.Fatal(err)
 74→	}
 75→
 76→	mcpClient := mcp.NewClient(&mcp.Implementation{Name: "test-client", Version: "0.0.1"}, nil)
 77→	cSession, err := mcpClient.Connect(ctx, ct, nil)
 78→	if err != nil {
 79→		t.Fatal(err)
 80→	}
 81→
 82→	cleanup := func() {
 83→		_ = cSession.Close()
 84→		_ = sSession.Close()
 85→		apiSrv.Close()
 86→	}
 87→	return cSession, cleanup
 88→}
