 90→func callTool(t *testing.T, cs *mcp.ClientSession, name string, args map[string]any) *mcp.CallToolResult {
 91→	t.Helper()
 92→	result, err := cs.CallTool(context.Background(), &mcp.CallToolParams{
 93→		Name:      name,
 94→		Arguments: args,
 95→	})
 96→	if err != nil {
 97→		t.Fatalf("CallTool(%s) error: %v", name, err)
 98→	}
 99→	return result
100→}
