 86→// CreateTask creates a new task.
 87→func (c *Client) CreateTask(body map[string]any) (*models.Task, error) {
 88→	data, err := c.do("POST", "/tasks", body)
 89→	if err != nil {
 90→		return nil, err
 91→	}
 92→
 93→	var task models.Task
 94→	if err := json.Unmarshal(data, &task); err != nil {
 95→		return nil, fmt.Errorf("failed to parse task: %w", err)
 96→	}
 97→	return &task, nil
 98→}
