132→var collapseWS = regexp.MustCompile(`\s+`)
133→
134→// normalizeWhitespace trims and collapses runs of whitespace to a single space.
135→func normalizeWhitespace(s string) string {
136→	return collapseWS.ReplaceAllString(strings.TrimSpace(s), " ")
137→}
138→
139→// maxFindPages limits the number of pages FindTaskByName will fetch
140→// to avoid unbounded iteration (20 pages × 50 tasks/page = 1000 tasks).
141→const maxFindPages = 20
142→
143→// FindTaskByName searches for a task by partial name matching across all pages.
144→// Exact matches take priority over partial matches. Returns nil if no match is found.
145→func (c *Client) FindTaskByName(name string) (*models.Task, error) {
146→	norm := strings.ToLower(normalizeWhitespace(name))
147→
148→	var partial *models.Task
149→	cursor := ""
150→	for range maxFindPages {
151→		tasks, nextCursor, err := c.getTasksPage("", cursor)
