	_, err := c.do("DELETE", "/tasks/"+id, nil)
	return err
}

// CloseTask marks a task as complete.
func (c *Client) CloseTask(id string) error {
	_, err := c.do("POST", "/tasks/"+id+"/close", nil)
	return err
}

