		switch {
		case cursor == "" && page == 0:
			page++
			_, _ = w.Write([]byte(`{"results":[
				{"id":"1","content":"First page task"}
			],"next_cursor":"page2"}`))
		case cursor == "page2":
			page++
			_, _ = w.Write([]byte(`{"results":[
				{"id":"2","content":"Second page task"},
				{"id":"3","content":"TEST: verify MCP bug fixes"}
			],"next_cursor":""}`))
		default:
			t.Errorf("unexpected cursor = %q, page = %d", cursor, page)
