	c, srv := testServer(t, func(w http.ResponseWriter, r *http.Request) {
		pageCount++
		// Always return a non-empty cursor to simulate infinite pagination.
		_, _ = w.Write([]byte(`{"results":[
			{"id":"1","content":"Unrelated task"}
		],"next_cursor":"next"}`))
