func TestFindTaskByName_pagination(t *testing.T) {
	page := 0
	c, srv := testServer(t, func(w http.ResponseWriter, r *http.Request) {
		cursor := r.URL.Query().Get("cursor")
		switch {
		case cursor == "" && page == 0:
